    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= _value);
        uint beforeBalance = address(this).balance;
        bool reverted;
        c.sendMoney(address(this), _value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(reverted || address(this).balance == beforeBalance + _value);
    }

    receive() external payable {}
}

